/**
 * The header banner prepended to generated files.
 *
 * It is applied in the pipeline after rendering and before rustfmt, so it also
 * covers files produced by user templates — no template has to repeat it.
 *
 * Two banners exist, matching the two ownership classes:
 *
 *  - **managed** files are regenerated on every run, so they open with the
 *    `@generated ... Do not edit by hand.` marker that editors, code hosts and
 *    review tools use to recognise generated files.
 *  - **create-only** files (the scaffold) are written once and then owned by
 *    the project, so they get an "edit me" notice instead. They are deliberately
 *    *not* marked `@generated`, because hand-editing them is the intended use.
 *
 * The comment syntax follows the file type: `//` for Rust, `#` for
 * TOML/gitignore and `--` for SQL. A file type with no known syntax is left
 * untouched rather than guessed at.
 */

/** Exact file names that need a syntax not implied by their extension. */
const BY_NAME: Record<string, string> = {
  ".gitignore": "#",
};

/** Comment prefix per output extension. Add new output types here. */
const BY_EXTENSION: Record<string, string> = {
  ".rs": "//",
  ".toml": "#",
  ".sql": "--",
};

/** Which banner a file gets; mirrors {@link RenderJob.ownership}. */
export type BannerOwnership = "managed" | "create-only";

const MANAGED_MESSAGE = [
  "@generated by @em/codegen. Do not edit by hand.",
  "Edit the spec or the templates, then rerun `em-codegen gen`.",
];

const CREATE_ONLY_MESSAGE = [
  "Scaffolded by @em/codegen. This file is yours to edit.",
  "It is written once and never overwritten by `em-codegen gen`.",
];

/** The banner comment for an output path, or `null` when the type is unknown. */
export function bannerFor(
  outPath: string,
  ownership: BannerOwnership = "managed",
): string | null {
  const base = outPath.split("/").pop() ?? outPath;
  const dot = base.lastIndexOf(".");
  const prefix =
    BY_NAME[base] ?? (dot > 0 ? BY_EXTENSION[base.slice(dot)] : undefined);
  if (!prefix) return null;
  const message = ownership === "create-only" ? CREATE_ONLY_MESSAGE : MANAGED_MESSAGE;
  return message.map((line) => `${prefix} ${line}`).join("\n") + "\n\n";
}

/** Prepends the banner to `content`, or returns it unchanged for unknown types. */
export function withBanner(
  outPath: string,
  content: string,
  ownership: BannerOwnership = "managed",
): string {
  const banner = bannerFor(outPath, ownership);
  return banner ? banner + content : content;
}
